local mainMod = "SUPER"

-- Sets "Windows" key as main modifier

hl.bind(mainMod .. " + " .. "SHIFT" .. " + " .. "W", hl.dsp.exec_cmd("switch-wallpaper"))

hl.bind(mainMod .. " + " .. "N", hl.dsp.exec_cmd("toggle-night-mode"))

hl.bind(mainMod .. " + " .. "L", hl.dsp.exec_cmd("toggle-min-mode"))

hl.bind(mainMod .. " + " .. "W", hl.dsp.exec_cmd("toggle-waybar"))

